def is_balanced(s):
    # Walk the string once, tracking how many brackets are currently open.
    # Every opener increases the depth and every closer decreases it. If the
    # depth ever goes negative a closer arrived with nothing to close, and if
    # the depth is non-zero at the end some opener was never closed.
    depth = 0
    for character in s:
        if character in "([{":
            depth += 1
        elif character in ")]}":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

