def is_balanced(s):
    # Map every closing bracket to the opening bracket it must match. Any
    # character that is not a bracket is ignored entirely, which is what the
    # specification asks for: the function inspects bracket structure only and
    # treats all other text as filler.
    closing_to_opening = {")": "(", "]": "[", "}": "{"}
    stack = []
    for character in s:
        if character in "([{":
            # An opening bracket always pushes; it can only be resolved later.
            stack.append(character)
        elif character in closing_to_opening:
            # A closing bracket must match the most recent unmatched opener.
            if not stack:
                return False
            if stack.pop() != closing_to_opening[character]:
                return False
    # Anything still on the stack is an opener that was never closed.
    return len(stack) == 0

